function power(base: number, exp: number): number {
    if (exp === 0) return 1
    const half = power(base, Math.floor(exp / 2))
    return exp % 2 === 0 ? half * half : half * half * base
}
console.log(power(2, 10), power(3, 5), power(5, 0))

