function hanoi(n: number, from: string, to: string, via: string, moves: string[] = []): string[] {
    if (n === 0) return moves
    hanoi(n - 1, from, via, to, moves)
    moves.push(`${from}->${to}`)
    hanoi(n - 1, via, to, from, moves)
    return moves
}
const moves = hanoi(3, "A", "C", "B")
