type OrderItem = { name: string; price: number; qty: number }

function subtotal(items: OrderItem[]): number {
    return items.reduce((sum, item) => sum + item.price * item.qty, 0)
}

function applyDiscount(amount: number, percent: number): number {
    return Math.round(amount * (1 - percent / 100))
}

function formatMoney(amount: number): string {
    return amount.toLocaleString("en-US").replace(/,/g, " ") + " so'm"
}

function orderSummary(items: OrderItem[], discountPercent = 0): string {
    const total = applyDiscount(subtotal(items), discountPercent)
    return `${items.length} ta mahsulot, jami: ${formatMoney(total)}`
}

