function reduceList<T, A>(items: T[], fn: (acc: A, item: T) => A, init?: A): A {
    const hasInit = init !== undefined
    let acc = (hasInit ? init : items[0]) as A
    for (const item of hasInit ? items : items.slice(1)) acc = fn(acc, item)
    return acc
}

