class Countdown implements Iterable<number> {
    constructor(private start: number) {}

    [Symbol.iterator](): Iterator<number> {      // qo'lda: holat va next() ni o'zingiz yozasiz
        let current = this.start
        return {
            next: (): IteratorResult<number> =>
                current > 0 ? { value: current--, done: false } : { value: undefined, done: true },
        }
    }
}

class CountdownGen implements Iterable<number> {
    constructor(private start: number) {}

    *[Symbol.iterator](): Generator<number> {    // generator bilan: bir necha qator
        for (let n = this.start; n > 0; n--) yield n
    }
}

const a = [...new Countdown(3)]       // [3, 2, 1]
