type Node = { name: string; children?: Node[] }

function* walk(node: Node, depth = 0): Generator<string> {
    yield "  ".repeat(depth) + node.name
    for (const child of node.children ?? []) yield* walk(child, depth + 1)
}

const tree: Node = { name: "src", children: [{ name: "app.ts" }, { name: "utils", children: [{ name: "date.ts" }] }] }
for (const line of walk(tree)) console.log(line)

type Command = "coin" | "push"

function* turnstile(): Generator<string, void, Command> {
    let locked = true
    while (true) {
        const command: Command = yield locked ? "yopiq" : "ochiq"
        if (command === "coin") locked = false
        else locked = true
    }
}

const gate = turnstile()
console.log(gate.next().value)            // boshlang'ich holat
console.log(gate.next("push").value)
console.log(gate.next("coin").value)
console.log(gate.next("push").value)

class TreeNode {
    constructor(
        public value: number,
        public left?: TreeNode,
        public right?: TreeNode,
    ) {}

    *[Symbol.iterator](): Generator<number> {
        if (this.left) yield* this.left
        yield this.value
        if (this.right) yield* this.right
    }
}

const tree = new TreeNode(5, new TreeNode(3, new TreeNode(1), new TreeNode(4)), new TreeNode(8))
console.log([...tree])

