function* fibonacci(): Generator<number> {
    let [a, b] = [0, 1]
    while (true) {
        yield a
        ;[a, b] = [b, a + b]
    }
}

function* takeWhile<T>(source: Iterable<T>, predicate: (x: T) => boolean): Generator<T> {
    for (const item of source) {
        if (!predicate(item)) return
        yield item
    }
}

console.log([...takeWhile(fibonacci(), n => n < 100)])

function* take<T>(src: Iterable<T>, n: number) {
    if (n <= 0) return
    for (const x of src) { yield x; if (--n === 0) return }
}
function* naturals() { let i = 1; while (true) yield i++ }
console.log([...take(naturals(), 7)])

