class Registry<V> {
    private items = new Map<string, V>()

    set(key: string, value: V): this {
        this.items.set(key, value)
        return this
    }

    *keys(): Generator<string> {
        yield* this.items.keys()
    }

    *entries(): Generator<[string, V]> {
        yield* this.items.entries()
    }

    [Symbol.iterator](): Generator<[string, V]> {
        return this.entries()
    }
}

const registry = new Registry<number>().set("a", 1).set("b", 2)
console.log([...registry.keys()])
for (const [key, value] of registry) console.log(key, value)

