function* combinations<T>(arr: T[], k: number, start = 0, cur: T[] = []): Generator<T[]> {
    if (cur.length === k) { yield [...cur]; return }
    for (let i = start; i < arr.length; i++) {
        cur.push(arr[i])
        yield* combinations(arr, k, i + 1, cur)
        cur.pop()
    }
}
console.log([...combinations(["A", "B", "C", "D"], 2)].map(c => c.join("")))

