function* entriesOf<T extends object>(obj: T): Generator<[keyof T, T[keyof T]]> {
    for (const key of Object.keys(obj) as (keyof T)[]) {
        yield [key, obj[key]]
    }
}

const product = { name: "Choy", price: 25_000, inStock: true }
for (const [key, value] of entriesOf(product)) {
    console.log(`${String(key)} = ${value}`)
}

class AsyncCountdown implements AsyncIterable<number> {
    constructor(private from: number) {}

    async *[Symbol.asyncIterator](): AsyncGenerator<number> {
        for (let n = this.from; n > 0; n--) {
            await new Promise(resolve => setTimeout(resolve, 1))
            yield n
        }
    }
}

for await (const n of new AsyncCountdown(3)) {
    console.log(n)
}

function* lines(text: string): Generator<string> {
    for (const line of text.split("\n")) {
        if (line.trim() !== "") yield line
    }
}

function* parseRows(rows: Iterable<string>): Generator<{ name: string; score: number }> {
    for (const row of rows) {
        const [name, score] = row.split(",")
        yield { name, score: Number(score) }
    }
}

const csv = "Ali,90\nVali,72\n\nSoli,85"
const best = Iterator.from(parseRows(lines(csv)))
    .filter(row => row.score >= 80)
    .map(row => row.name)
    .toArray()

console.log(best)
